mapper.update:
update t_bill_cash
method = #{method}, `type` = #{type}, order_no = #{orderNo}, failure_reason = #{failureReason}, user_id = #{userId}, scene = #{scene}, `describe` = #{describe}, zfb_name = #{zfbName}, zfb_user_name = #{zfbUserName}, money = #{money}, status = #{status}, withdrawal_tab_id = #{withdrawalTabId}, auto_account = #{autoAccount}, take = #{take}, pay_time = #{payTime}, create_time = #{createTime}, update_time = #{updateTime}, method = #{method}, package_info = #{packageInfo},
where id = #{id}

mapper.select:
SELECT tbc.id, tbc.method,tbc.type, tbc.order_no orderNo, tbc.failure_reason failureReason, tbc.user_id userId,
tbc.scene, tbc.`describe`, tbc.money, tbc.status, tbc.withdrawal_tab_id withdrawalTabId,
tbc.auto_account autoAccount, tbc.pay_time payTime, tbc.create_time createTime, tbc.update_time updateTime ,
tu.nick_name nickName,tu.avatar,tu.commander,tu2.nick_name commanderUserName,
tbc.zfb_name zfbName,tbc.zfb_user_name zfbUserName
from t_bill_cash tbc
INNER JOIN t_user tu on tu.id=tbc.user_id
LEFT JOIN t_user tu2 on tu2.id=tu.parent_id
where 1=1
 and tbc.method=#{method}
 and tbc.type=#{type}
 and tbc.scene=#{scene}
and tu.commander = #{commander}
 and tbc.status=#{status}
 and tbc.auto_account=#{autoAccount}
 and tu.nick_name like concat('%', #{nickName}, '%')
and tu2.nick_name like concat('%', #{commanderUserName}, '%')
ORDER BY tbc.create_time DESC

